async page => {
  const ref = name => page.locator('[data-ref="'+name+'"]');
  const check = (condition, message) => { if (!condition) throw Error(message); };
  const evidence = () => page.evaluate(() => ({ modelCalls:localEvidence.modelCalls, groupWrites:localEvidence.groupWrites, current:localEvidence.current }));
  const open = async () => {
    await page.goto('http://127.0.0.1:8767/v022.html?site=aihub&pelican&platforms');
    await page.locator('#kf-tab-monitor').click();
  };
  const routing = async () => { await page.locator('#kf-tab-settings').click(); await page.locator('[data-settings-target=routing]').click(); };
  await page.setViewportSize({ width:1360, height:1000 });
  await page.emulateMedia({ colorScheme:'dark', reducedMotion:'no-preference' });
  await open();
  await ref('candidatePlatform').selectOption('kimi');
  await ref('check').click();
  await ref('candidateRows').locator('.candidate').first().waitFor();
  await routing();
  await ref('automaticSwitchMode').selectOption('strategy');
  await page.clock.install();
  await ref('enabled').check(); await page.clock.fastForward(1000);
  await ref('status').filter({hasText:/已检查.*API 密钥/}).waitFor();
  check((await evidence()).groupWrites.length===0 && (await evidence()).modelCalls===0,'strategy keeps healthy outside group without scoring');
  await ref('automaticSwitchMode').selectOption('failover'); await page.clock.fastForward(1000);
  await page.evaluate(()=>{localEvidence.unknown=true;}); await page.clock.fastForward(16000);
  await ref('status').filter({hasText:/已检查.*API 密钥/}).waitFor();
  check((await evidence()).groupWrites.length===0,'unknown outside group is not a fault');
  await page.evaluate(()=>{localEvidence.unknown=false;localEvidence.fault=true;}); await page.clock.fastForward(16000);
  await page.waitForFunction(()=>localEvidence.current===4);
  const recovered = await evidence();
  check(recovered.groupWrites.length===1 && recovered.groupWrites[0].group===4,'fault recovers only to Kimi using saving strategy');
  check(recovered.modelCalls===0,'fault recovery skips image scoring');
  await page.evaluate(()=>{localEvidence.fault=false;}); await page.clock.fastForward(16000);
  await ref('status').filter({hasText:/已检查.*API 密钥/}).waitFor();
  check((await evidence()).groupWrites.length===1,'no automatic return to outside group');
  await ref('enabled').uncheck(); await page.clock.resume();
  // Empty intersection: configured platform is Grok, whitelist contains only OpenAI.
  await open();
  await ref('candidatePlatform').selectOption('grok');
  await ref('check').click(); await ref('candidateRows').locator('.candidate').first().waitFor();
  await routing(); await ref('groupFilterSelectToggle').click();
  await ref('groupFilterList').locator('input[data-group-name="openai-01"]').check();
  await ref('groupFilterSelectToggle').click();
  await ref('enabled').check(); await page.clock.fastForward(1000);
  await page.evaluate(()=>{localEvidence.fault=true;}); await page.clock.fastForward(16000);
  const empty = await evidence();
  check(empty.groupWrites.length===0 && empty.modelCalls===0,'empty intersection never borrows a group or image call');
  await page.locator('#kf-tab-monitor').click();
  await page.locator('#kf-tab-diagnostics').click();
  await ref('tokenResultRows').filter({hasText:'没有可恢复'}).waitFor();
  await page.locator('#kf-tab-monitor').click();
  await ref('manualSwitch').click();
  check(await ref('manualGroup').locator('input[data-manual-group]').count()===40,'manual directory stays complete');
  await ref('manualGroup').locator('input[data-manual-group="deepseek-02"]').check();
  await ref('manualConfirm').click();
  await page.waitForFunction(()=>localEvidence.groupWrites.length===1);
  check((await evidence()).current===2 && (await evidence()).modelCalls===0,'explicit outside manual destination retains override and skips images');
  await routing(); await ref('enabled').uncheck();
  await page.evaluate(()=>{localEvidence.failKeys=true;});
  await page.locator('#kf-tab-monitor').click(); await ref('check').click();
  await ref('status').filter({hasText:'处理失败'}).waitFor();
  check((await ref('status').innerText()).includes('失败'),'expired key error is visible');
  await ref('candidatePlatform').selectOption('kimi');
  check(await ref('candidatePlatform').inputValue()==='kimi','scope remains operable after error');
  await page.screenshot({path:'C:/Users/sj930/Documents/Codex/2026-10-22/kfcoding-aihub-ooioo-fluxionai-users-shenjian/outputs/playwright/platform-scope/error-runtime.png'});
  await page.clock.resume();
  return { recovered, empty, final:await evidence(), environment:'real Chromium; all service IO and group writes simulated; no paid calls' };
}
